import struct

def rotate_left(value, bits, size=32):
    return ((value << bits) | (value >> (size - bits))) & ((1 << size) - 1)

def process_block(block, method=0):
    # Convert block to integer (try both endianness)
    if method == 0:
        val = struct.unpack('<I', block)[0]  # little endian
    else:
        val = struct.unpack('>I', block)[0]  # big endian

    # XOR with key first
    key = b'Elyk'
    if method == 0:
        key_val = struct.unpack('<I', key)[0]
    else:
        key_val = struct.unpack('>I', key)[0]

    val ^= key_val

    # Then rotate left
    val = rotate_left(val, 1)

    return val

